`timescale 1ns / 1ps
// Self-checking testbench for the lab4 core. core/rom.mem is the assembled
// mem_test.s, whose comments document both the cache hit/miss sequence and the
// expected register results. ram.mem holds F0F0F0F0 at 0x1C; everything the
// program touches at 0x200/0x400/0x410 reads back as zero.
module tb_lab4;
    reg clk, rst;
    wire [31:0] debug_data, wb_pc, wb_inst, mem_addr, mem_data;

    RV32core core(
        .debug_en(1'b0),.debug_step(1'b0),.debug_addr(7'b0),.debug_data(debug_data),
        .clk(clk),.rst(rst),.wb_pc(wb_pc),.wb_inst(wb_inst),
        .mem_addr(mem_addr),.mem_data(mem_data),.interrupter(1'b0)
    );

    initial begin clk = 0; rst = 1; #4 rst = 0; end
    always #1 clk = ~clk;

    integer errors = 0;

    task check_reg(input[4:0] idx, input[31:0] want, input[8*40-1:0] what);
        reg [31:0] got;
        begin
            got = core.register.register[idx];
            if (got !== want) begin
                $display("MISMATCH x%0d (%0s): got %h expected %h", idx, what, got, want);
                errors = errors + 1;
            end
            else $display("ok x%0d = %h (%0s)", idx, got, what);
        end
    endtask

    // the program ends in `loop: ori x16,x0,0xED; jal x0,loop` at PC 0x3c/0x40
    integer spins = 0;
    always @(posedge clk) if (!rst && wb_pc == 32'h40) spins = spins + 1;

    initial begin
        #1600;
        $display("");
        if (spins == 0) begin
            $display("ERROR: program never reached the final loop (wb_pc=%h)", wb_pc);
            errors = errors + 1;
        end

        // byte/half/word loads with sign and zero extension out of 0x1C = F0F0F0F0
        check_reg(2,  32'hFFFFF0F0, "lh  0x1C");
        check_reg(3,  32'hF0F0F0F0, "lw  0x1C");
        check_reg(4,  32'h000000F0, "lbu 0x1C");
        check_reg(5,  32'h0000F0F0, "lhu 0x1C");
        // lui+addi, forwarded EX->ID
        check_reg(1,  32'hABCDE71C, "lui+addi");
        // these lines are zero filled in data_ram
        check_reg(6,  32'h00000000, "lw  0x200");
        check_reg(7,  32'h00000000, "lw  0x400 (after dirty write-back)");
        check_reg(8,  32'h00000000, "lw  0x410");
        check_reg(16, 32'h000000ED, "ori 0xED");

        if (errors == 0) $display("LAB4 TEST PASSED");
        else $display("LAB4 TEST FAILED with %0d errors", errors);
        $finish;

