               {5{LW}}           & `MEM_LW     |
               {5{LBU}}          & `MEM_LBU    |
               {5{LHU}}          & `MEM_LHU    |
               {5{SB}}           & `MEM_SB     |
               {5{SH}}           & `MEM_SH     |
               {5{SW}}           & `MEM_SW     |
               {5{MUL}}          & `MUL_MUL    |
               {5{MULH}}         & `MUL_MULH   |
               {5{MULHSU}}       & `MUL_MULHU  |
               {5{MULHU}}        & `MUL_MULHSU |
               {5{DIV}}          & `DIV_DIV    |
               {5{DIVU}}         & `DIV_DIVU   |
               {5{REM}}          & `DIV_REM    |
               {5{REMU}}         & `DIV_REMU   |
               {5{BEQ}}          & `JUMP_BEQ   |
               {5{BNE}}          & `JUMP_BNE   |
               {5{BLT}}          & `JUMP_BLT   |
               {5{BGE}}          & `JUMP_BGE   |
               {5{BLTU}}         & `JUMP_BLTU  |
               {5{BGEU}}         & `JUMP_BGEU  |

               {5{BGEU}}         & `JUMP_BGEU  |
               {5{JAL}}          & `JUMP_JAL   |
               {5{JALR}}         & `JUMP_JALR  ;


assign ImmSel = {3{JALR | L_valid | I_valid}} & `Imm_type_I |
                {3{B_valid}}                  & `Imm_type_B |
                {3{JAL}}                      & `Imm_type_J |
                {3{S_valid}}                  & `Imm_type_S |
                {3{LUI | AUIPC}}              & `Imm_type_U ;

// ensure WAR:
