// Simulation models of the two Vivado IP cores the FUs instantiate. The real
// cores are generated from the IP catalog (see docs/lab5.md); these reproduce
// the configured behaviour so the design can be simulated with iverilog.
//
// They deliberately live under agent_tests/ rather than repo/src so the design
// sources still expect the genuine IP to be supplied at build time.

// Multiplier 12.0: parallel, signed 32 x signed 32 -> 64, 5 pipeline stages,
// no CE / SCLR.
module multiplier(
    input CLK,
    input[31:0] A,
    input[31:0] B,
    output[63:0] P
);
    reg[63:0] pipe[0:4];
    integer i;
    initial for (i = 0; i < 5; i = i + 1) pipe[i] = 64'b0;

    always @ (posedge CLK) begin
        pipe[0] <= $signed(A) * $signed(B);
        for (i = 1; i < 5; i = i + 1) pipe[i] <= pipe[i-1];
    end

    assign P = pipe[4];
endmodule


// Divider Generator 5.1: Radix2, signed, 32-bit dividend / 32-bit divisor,
// remainder output. dout carries {quotient, remainder}. Radix2 latency scales
// with the operand width; the exact figure only shifts when results land, not
// what they are.
module divider #(parameter LATENCY = 36) (
    input aclk,
    input s_axis_dividend_tvalid,
    input[31:0] s_axis_dividend_tdata,
    input s_axis_divisor_tvalid,
    input[31:0] s_axis_divisor_tdata,
    output m_axis_dout_tvalid,
    output[63:0] m_axis_dout_tdata
);
    reg[63:0] pipe[0:LATENCY-1];
    reg valid[0:LATENCY-1];
    integer i;
    initial for (i = 0; i < LATENCY; i = i + 1) begin
        pipe[i] = 64'b0;
        valid[i] = 1'b0;
    end

    wire start = s_axis_dividend_tvalid & s_axis_divisor_tvalid;

    wire signed[31:0] a = s_axis_dividend_tdata;
    wire signed[31:0] b = s_axis_divisor_tdata;

    // the IP leaves the result undefined for a zero divisor rather than trapping
    wire[31:0] quotient  = (b == 0) ? 32'hFFFFFFFF : a / b;
    wire[31:0] remainder = (b == 0) ? a            : a % b;

