        // out of order: sub retires ahead of the lw x7 issued before it
        expect_wb(1,  32'h00000008,  30,  "sub x1,x4,x2 (OoO before lw x7)");
        expect_wb(7,  32'h0fff0000,  31,  "lw x7,20(x0)");
        expect_wb(1,  32'hfffffffd,  34,  "addi x1,x10,-3");
        // the first beq is not taken, the second is, so both addi at 0x30.. are skipped
        expect_wb(1,  32'h00004000,  43,  "lui x1,4 (branch target)");
        expect_wb(1,  32'h00000048,  47,  "jal x1,12 (link = 0x44+4)");
        expect_wb(1,  32'hffff0050,  51,  "auipc x1,0xffff0 (jal target)");
        // out of order: the 6-cycle mul retires while the 36-cycle div still runs
        expect_wb(9,  32'h00000140,  59,  "mul x9,x4,x5 (OoO before div x8)");
        expect_wb(1,  32'h00000068,  65,  "jalr x1,0(x0) (restarts program)");
        expect_wb(8,  32'h01ffe000,  88,  "div x8,x7,x2");

        // WAR: `addi x2,x0,4` follows `mul x9,x8,x2` in program order, so it may
        // not overwrite x2 until the multiply has read it. The multiply therefore
        // still sees x2 = 8; a broken WAR check yields 0x01ffe000*4 = 0x07ff8000.
        expect_wb(2,  32'h00000004,  90,  "addi x2,x0,4 (WAR: after mul read x2)");
        // the jalr restarted the program, so its `lw x2,4(x0)` lands here. It was
        // held off until the addi above retired, which is the WAW interlock.
        expect_wb(2,  32'h00000008,  96,  "lw x2,4(x0) of the restarted program");
        expect_wb(9,  32'h0fff0000,  97,  "mul x9,x8,x2 (WAR: used old x2=8)");

        $display("");
        $display("%0d write-backs observed, clk_counter = %0d", n_wb, clk_counter);
        if (n_wb == 0) begin
            $display("ERROR: the core never wrote back a register");
            errors = errors + 1;
        end

        if (errors == 0) $display("LAB5 TEST PASSED");
        else $display("LAB5 TEST FAILED with %0d errors", errors);
        $finish;
    end
endmodule

