`timescale 1ns / 1ps
// Self-checking testbench for the lab5 scoreboard core.
//
// core/rom.mem is the assembled ref/inst.S, whose comments record the value each
// instruction writes back. The program ends in `jalr x1,0(x0)` which restarts it,
// so rather than sampling the register file at the end we record the write-back
// trace and check the first pass through the program.
//
// The trace is what makes this a scoreboard test: the expected order is *not*
// program order. `sub x1,x4,x2` retires before the `lw x7` that precedes it, and
// `mul x9,x4,x5` retires before the earlier `div x8`, because the FUs have
// different latencies and complete out of order.
module tb_lab5;
    reg clk, rst;
    wire[31:0] debug_data, wb_addr, wb_data, clk_counter;

    RV32core core(
        .debug_en(1'b0),.debug_step(1'b0),.debug_addr(7'b0),.debug_data(debug_data),
        .wb_addr(wb_addr),.wb_data(wb_data),.clk_counter(clk_counter),
        .clk(clk),.rst(rst),.interrupter(1'b0)
    );

    initial begin clk = 0; rst = 1; #4 rst = 0; end
    always #1 clk = ~clk;

    integer errors = 0;

    // ---- capture the write-back trace -------------------------------------
    localparam MAX_WB = 64;
    reg[4:0]  wb_reg_log[0:MAX_WB-1];
    reg[31:0] wb_val_log[0:MAX_WB-1];
    integer n_wb = 0;

    always @(posedge clk) if (!rst) begin
        if (core.RegWrite_ctrl && |wb_addr && n_wb < MAX_WB) begin
            wb_reg_log[n_wb] = wb_addr[4:0];
            wb_val_log[n_wb] = wb_data;
            n_wb = n_wb + 1;
        end
    end

    integer idx = 0;
    task expect_wb(input[4:0] r, input[31:0] v, input[8*32-1:0] what);
        begin
            if (idx >= n_wb) begin
                $display("MISSING  #%0d: expected x%0d = %h (%0s)", idx, r, v, what);
                errors = errors + 1;
            end
            else if (wb_reg_log[idx] !== r || wb_val_log[idx] !== v) begin
                $display("MISMATCH #%0d: got x%0d = %h, expected x%0d = %h (%0s)",
                         idx, wb_reg_log[idx], wb_val_log[idx], r, v, what);
                errors = errors + 1;
            end
            else $display("ok #%0d x%0d = %h (%0s)", idx, r, v, what);
            idx = idx + 1;
        end
    endtask

    initial begin
        #4000;

        // ---- in-order prefix, up to the jalr that restarts the program ----
        expect_wb(2,  32'h00000008, "lw x2,4(x0)");
        expect_wb(4,  32'h00000010, "lw x4,8(x0)");
        expect_wb(1,  32'h00000018, "add x1,x2,x4");
        expect_wb(1,  32'h00000017, "addi x1,x1,-1");
        expect_wb(5,  32'h00000014, "lw x5,12(x0)");
        expect_wb(6,  32'hffff0000, "lw x6,16(x0)");
        // out of order: sub retires ahead of the lw x7 issued before it
        expect_wb(1,  32'h00000008, "sub x1,x4,x2 (OoO before lw x7)");
        expect_wb(7,  32'h0fff0000, "lw x7,20(x0)");
        expect_wb(1,  32'hfffffffd, "addi x1,x10,-3");
        expect_wb(1,  32'h00004000, "lui x1,4");
        expect_wb(1,  32'h00000030, "jal x1,12");
        expect_wb(1,  32'hffff0050, "auipc x1,0xffff0");
        // out of order: the 6-cycle mul retires while the div is still running
        expect_wb(9,  32'h00000140, "mul x9,x4,x5 (OoO before div x8)");
        expect_wb(1,  32'h00000068, "jalr x1,0(x0)");
        expect_wb(8,  32'h01ffe000, "div x8,x7,x2");

        // ---- WAR: `addi x2,x0,4` may not overwrite x2 until `mul x9,x8,x2`
        // has read it, so the multiply must still see the old x2 = 8.
        // A broken WAR check gives 0x01ffe000*4 = 0x07ff8000 instead.
        expect_wb(2,  32'h00000004, "addi x2,x0,4 (WAR: after mul reads x2)");
        expect_wb(9,  32'h0fff0000, "mul x9,x8,x2 (WAR: used old x2=8)");

        $display("");
        $display("%0d write-backs observed, clk_counter = %0d", n_wb, clk_counter);
        if (n_wb == 0) begin
            $display("ERROR: the core never wrote back a register");
            errors = errors + 1;
        end

        if (errors == 0) $display("LAB5 TEST PASSED");
        else $display("LAB5 TEST FAILED with %0d errors", errors);
        $finish;
    end
endmodule
